INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 1 (TPS 2003): Mistura lingüística Muita gente, em vários países, fala um pouco de inglês todo dia sem perceber. Sem contar o “informatiquês”, cujos verbetes — como megabyte, browser, hard disk, software — são expressões do mais puro inglês, muitas outras palavras do dia-a-dia de brasileiros, franceses, alemães e, principalmente, japoneses têm origem no idioma bretão. Futebol (football), sanduíche (sandwich) e deletar (verbo criado a partir de to delete, suprimir) são exemplos conhecidos de anglicismo (uso de expressões em inglês ou originadas dele) no português. Os alemães apertam o resetknopf (reset button ou botão de reset) para iniciar o computador. E os franceses, conhecidos por sua ojeriza a estrangeirismos, despedem-se dos colegas de trabalho na sexta-feira dizendo bon weekend. A situação do japonês é particularmente curiosa. Estima-se que cerca de vinte mil palavras do vocabulário moderno tenham origem no inglês. Sorvete é aisukurimu, de ice cream. Ar condicionado é eaco', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 2 (TPS 2003): Mistura lingüística Muita gente, em vários países, fala um pouco de inglês todo dia sem perceber. Sem contar o “informatiquês”, cujos verbetes — como megabyte, browser, hard disk, software — são expressões do mais puro inglês, muitas outras palavras do dia-a-dia de brasileiros, franceses, alemães e, principalmente, japoneses têm origem no idioma bretão. Futebol (football), sanduíche (sandwich) e deletar (verbo criado a partir de to delete, suprimir) são exemplos conhecidos de anglicismo (uso de expressões em inglês ou originadas dele) no português. Os alemães apertam o resetknopf (reset button ou botão de reset) para iniciar o computador. E os franceses, conhecidos por sua ojeriza a estrangeirismos, despedem-se dos colegas de trabalho na sexta-feira dizendo bon weekend. A situação do japonês é particularmente curiosa. Estima-se que cerca de vinte mil palavras do vocabulário moderno tenham origem no inglês. Sorvete é aisukurimu, de ice cream. Ar condicionado é eaco', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
